def is_fund(D):
    if D == 0:
        return False
    if D % 4 == 1:
        return D != 1 and is_squarefree(D)
    if D % 4 == 0:
        e = D // 4
        return (e % 4 in (2, 3)) and is_squarefree(e)
    return False


